		public int failureCount() {
			return failures.get();
		}

		private void maybeFail(Object writeOwner) {
			if (owner.get() == writeOwner && armed.compareAndSet(true, false)) {
				failures.incrementAndGet();
				CountDownLatch pauseEntered = entered;
				CountDownLatch pauseRelease = release;
				if (pauseEntered != null) {
					pauseEntered.countDown();
					try {
						if (!pauseRelease.await(30, TimeUnit.SECONDS)) {
							throw new SailException("Timed out waiting to release the replacement fork failure");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new SailException("Interrupted while waiting to release the replacement fork failure",
								interrupted);
					}
				}
				throw failure;
			}
		}
